import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds each person's open figure at the end of the old year's last period (see PeriodCloser#openAt, over the old
 *  year's periods) to their carried figure for the new year's first period (the earliest period whose from-date falls
 *  in it), written as OPENING_SET; a person with nothing open gets no line, and nothing is carried when that period was
 *  not generated by this rollover (the year was rolled over already). Keeps the rollover, with the periods it
 *  generated and the openings it set, so it can be undone (see UndoRollover). Then writes ROLLOVER. */
public class CarryRollover {
    public void carry(@PathVariable("sheetId") String sheetId, @Val RolloverValues rollover,
            @Val GeneratePeriodsValues values, @Val GeneratedPeriods generated, PeriodRepository periods,
            PeriodCloser closer, PersonRepository people, OpeningRepository openings, RolloverRepository rollovers, Audit audit) {
        String sheet = sheetId.trim();
        Period last = rollover.oldPeriods().get(rollover.oldPeriods().size() - 1);
        Map<Long, BigDecimal> open = closer.openAt(sheet, rollover.oldPeriods(), last.to());
        Period first = periods.list(sheet).stream()
                .filter((p) -> !p.from().isBefore(values.from()) && !p.from().isAfter(values.to()))
                .min(Comparator.comparing(Period::from)).orElse(null);
        List<Long> set = new ArrayList<>();
        if (first != null && generated.ids().contains(first.id())) {
            for (Person person : people.list(sheet)) {
                BigDecimal amount = open.get(person.id());
                if (amount == null || amount.signum() == 0) {
                    continue;
                }
                set.add(openings.add(sheet, first.id(), person.id(), amount));
                audit.record("OPENING_SET sheet=" + sheet + " by=" + rollover.by() + " name=" + person.name()
                        + " period=" + first.name() + " amount=" + amount.setScale(2).toPlainString());
            }
        }
        rollovers.add(sheet, rollover.fy(), rollover.by(), generated.ids(), set);
        audit.record("ROLLOVER sheet=" + sheet + " by=" + rollover.by() + " fy=" + rollover.fy() + " periods="
                + generated.made());
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the year is yyyy, the one rolling it over is a steward, and the fiscal year has periods (those
 *  whose from-date falls in it). Publishes the old year's periods, and the next fiscal year's dates for the period
 *  generator, as generating that fiscal year does (see ValidateGenerateFiscalYear). */
public class ValidateRollover {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RolloverRequest request,
            SettingRepository settings, RoleRepository roles, PeriodRepository periods, Out<RolloverValues> rollover,
            Out<GeneratePeriodsValues> values) throws InvalidPeriodException {
        String sheet = sheetId.trim();
        String text = request == null || request.year() == null ? "" : request.year().trim();
        String by = request == null || request.by() == null ? "" : request.by().trim();
        if (!text.matches("\\d{4}")) {
            throw new InvalidPeriodException("The fiscal year must be a year yyyy");
        }
        if (!RoleRepository.STEWARD.equals(roles.roleOf(sheet, by))) {
            throw new InvalidPeriodException("Only a steward may roll a year over");
        }
        YearMonth first = YearMonth.of(Integer.parseInt(text), settings.fiscalStartMonth(sheet));
        LocalDate from = first.atDay(1);
        LocalDate to = first.plusMonths(11).atEndOfMonth();
        List<Period> old = periods.list(sheet).stream()
                .filter((p) -> !p.from().isBefore(from) && !p.from().isAfter(to))
                .sorted(Comparator.comparing(Period::from)).toList();
        if (old.isEmpty()) {
            throw new InvalidPeriodException("The fiscal year FY" + text + " has no periods");
        }
        rollover.set(new RolloverValues("FY" + text, old, by));
        YearMonth next = first.plusMonths(12);
        values.set(new GeneratePeriodsValues(next.atDay(1), next.plusMonths(11).atEndOfMonth(), by));
    }
}
package net.officefloor.hq.app.period;

import java.sql.Date;
import java.sql.ResultSet;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rollovers made on each sheet, each with the periods it generated and the opening balances it set, so the last
 *  one can be undone. */
@Repository
public class RolloverRepository {

    /** A rollover as kept: the old fiscal year, who made it, the sheet's today it was made on, and what it made. */
    public record Rollover(long id, String sheetId, String fy, String by, LocalDate madeOn, List<Long> periodIds,
            List<Long> openingIds, boolean undone) {
    }

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public RolloverRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    private static String idsText(List<Long> ids) {
        return ids.stream().map(String::valueOf).collect(Collectors.joining(","));
    }

    private static List<Long> parseIds(String text) {
        return text == null || text.isEmpty() ? List.of() : Arrays.stream(text.split(",")).map(Long::parseLong).toList();
    }

    /** Keeps a rollover, made on the sheet's today. */
    public void add(String sheetId, String fy, String by, List<Long> periodIds, List<Long> openingIds) {
        jdbc.update("INSERT INTO rollover (sheet_id, fy, made_by, made_on, period_ids, opening_ids) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, fy, by, Date.valueOf(sheets.today(sheetId)), idsText(periodIds), idsText(openingIds));
    }

    /** The sheet's last rollover, or null when it has none. */
    public Rollover last(String sheetId) {
        List<Rollover> found = jdbc.query("SELECT id, sheet_id, fy, made_by, made_on, period_ids, opening_ids, undone FROM rollover"
                + " WHERE sheet_id = ? ORDER BY id DESC LIMIT 1", (ResultSet rs, int n) -> new Rollover(rs.getLong("id"),
                        rs.getString("sheet_id"), rs.getString("fy"), rs.getString("made_by"),
                        rs.getObject("made_on", LocalDate.class), parseIds(rs.getString("period_ids")),
                        parseIds(rs.getString("opening_ids")), rs.getBoolean("undone")), sheetId);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether any claim of the sheet, whatever its status, is dated inside the period. */
    public boolean hasClaims(Period period) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND claim_date >= ? AND claim_date <= ?",
                Integer.class, period.sheetId(), Date.valueOf(period.from()), Date.valueOf(period.to()));
        return n != null && n > 0;
    }

    /** Whether the period has an opening balance other than the ones listed (one pasted on it by hand). */
    public boolean hasOtherOpenings(Period period, List<Long> openingIds) {
        List<Long> ids = jdbc.queryForList("SELECT id FROM opening WHERE sheet_id = ? AND period_id = ?", Long.class,
                period.sheetId(), period.id());
        return !openingIds.containsAll(ids);
    }

    /** Undoes the rollover: removes the openings it set and the periods it generated (with what was kept about them), and
     *  marks it undone; false when it was already undone. */
    public boolean undo(Rollover rollover) {
        if (jdbc.update("UPDATE rollover SET undone = TRUE WHERE id = ? AND undone = FALSE", rollover.id()) != 1) {
            return false;
        }
        for (long id : rollover.openingIds()) {
            jdbc.update("DELETE FROM opening WHERE sheet_id = ? AND id = ?", rollover.sheetId(), id);
        }
        for (long id : rollover.periodIds()) {
            jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_id = ?", rollover.sheetId(), id);
            jdbc.update("DELETE FROM period_log WHERE sheet_id = ? AND period_id = ?", rollover.sheetId(), id);
            jdbc.update("DELETE FROM period WHERE sheet_id = ? AND id = ?", rollover.sheetId(), id);
        }
        return true;
    }
}
# POST /api/sheets/{sheetId}/periods/rollover — roll a fiscal year (yyyy, FY<yyyy>) over: generate the next fiscal
# year's twelve periods exactly as generate-fy does, then add each person's open figure at the end of the old year's
# last period (the due of their claims that count, belonging to a period of the old year, OPEN or PENDING at that
# period's end) to their carried figure for the new year's first period (only when this rollover generated it),
# written as OPENING_SET; then keep the rollover so it can be undone (see rollover-undo), and ROLLOVER. A year
# that is not yyyy, a fiscal year with no periods, or anyone but a steward is a 400 and writes nothing. Responds with
# how many periods were made.
